cd $RUN/worktrees/L2/extensions/mentor/tests && cat > m36-silence.mjs <<'EOF'
// M3.6 ADAPT-5: silence is a state the engine can see. Pure module test.
// Run: node tests/m36-silence.mjs
import assert from "node:assert/strict";

const root = new URL("../", import.meta.url);
const { planTurn } = await import(new URL("core/turn-plan.ts", root).href);
const { PACE_PRESETS } = await import(new URL("core/pace.ts", root).href);
const loop = await import(new URL("core/loop.ts", root).href);

const now = new Date("2026-10-31T12:00:00.000Z");
const skill = {
  id: "cs/loops",
  name: "loops",
  domain: "cs",
  createdAt: "2026-01-01T00:00:00.000Z",
  level: "intermediate",
  diagnostic: { at: "2026-10-01T00:00:00.000Z", sessionId: "s1", correct: true },
  acquiredAt: null,
  redoDueAt: null,
  checks: [{ at: "2026-10-30T12:00:00.000Z", sessionId: "s1", kind: "check", correct: true, hintLevel: 0, solution: false, grader: "model" }],
};
const plan = (over = {}) =>
  planTurn({
    item: null,
    skill,
    phase: "ATTEMPT",
    goalType: "conceptual",
    prerequisiteGap: false,
    predictedR: 0.4,
    confidentWrong: 0,
    lastOutcomes: [skill.checks[0]],
    idleTurns: 0,
    now,
    pace: PACE_PRESETS.standard,
    ...over,
  });

// --- the bug: the same prompt re-renders forever ------------------------
// Three consecutive learner turns with no outcome must change the move, not
// repeat it. v0.2.0 had no representation of a silent learner at all.
const first = plan({ idleTurns: 0 });
const second = plan({ idleTurns: 1 });
const third = plan({ idleTurns: 2 });
assert.notDeepEqual(
  [first.demand, first.expect],
  [second.demand, second.expect],
  "the plan changes at the first silent turn",
);
assert.equal(second.demand, "recall", "a narrower question, not a repeat of the same rung");
assert.equal(third.expect, "questions", "two silent turns: ask what the learner thinks is happening");
assert.match(third.reasons.join(" "), /notional-machine|misconception/);

// --- the item ends at the pace budget, it does not repeat --------------
for (const id of ["drill", "standard"]) {
  const pace = PACE_PRESETS[id];
  const atBudget = plan({ pace, idleTurns: pace.maxTurnsPerItem });
  assert.equal(atBudget.phase, "CONSOLIDATE", `${id}: the item consolidates at its turn budget`);
  assert.equal(atBudget.expect, "silence", `${id}: and stops asking`);
  assert.match(atBudget.reasons.join(" "), /consolidate instead of repeating/);
  const before = plan({ pace, idleTurns: pace.maxTurnsPerItem - 1 });
  assert.notEqual(before.phase, "CONSOLIDATE", `${id}: one turn short of the budget still works the item`);
}

// --- the loop can carry the count the plan reads ----------------------
{
  const started = loop.start({ skillId: "cs/loops", goal: "g", goalType: "conceptual" }, { level: "intermediate", diagnostic: {} }, 1);
  assert.equal(started.state.idleTurns, 0, "a new loop starts with no silent turns");
  const advanced = loop.advance(started.state, "EXAMPLE", 2).state;
  assert.equal(advanced.idleTurns, 0, "a transition resets the count it left behind");
  // An outcome resets it too: a recorded attempt is not silence.
  const recorded = loop.record({ ...advanced, idleTurns: 2 }, "practice", false, null, 3).state;
  assert.equal(recorded.idleTurns, 0);
}
console.log("PASS M3.6 silence: the plan changes on a silent turn and the item ends at the pace budget");
EOF
