cd $RUN/worktrees/L6 && cat >> src/core/identity.ts <<'EOF'

/**
 * FIX-028: the operator commits the verified union in the integration worktree, which is a DIFFERENT git object store
 * from a lane's worktree. `episode_prepare` then refused every lane that named that commit ("commit object not present
 * in L4 isolated worktree"), because a commit the lane cannot read is a commit it cannot attest - the check is right.
 * What was missing was a path for "the artifact lives there, here is where": the only way out was to name the baseline,
 * a commit that provably does not contain the work. This is that path, and it is explicit: the caller names the
 * repository, the commit must already exist THERE (so a hash nobody has cannot be laundered into existence), and it is
 * fetched into the lane's own object store before the ordinary `checkCommit` proves it is readable there.
 *
 * Fetching refs rather than only the wanted sha is deliberate: a local transport may refuse an arbitrary-sha want, so
 * the artifact repository's branch tips are mirrored into a private `refs/xcomms/artifact/*` namespace first. That
 * namespace is not a branch, is never checked out, and changes no working tree.
 */
export function importCommit(input: { from: string; commit: string; into: string }): string {
  const from = resolve(input.from), into = resolve(input.into), commit = input.commit.toLowerCase();
  if (!HEX40.test(commit)) throw new XcError("E_BAD_ARG", `artifact commit must be 40-64 hex, got ${input.commit.length} chars`);
  if (git(["rev-parse", "--git-dir"], from) === null) {
    throw new XcError("E_BAD_ARG", `artifact repository ${from} is not a git repository`);
  }
  if (git(["cat-file", "-e", `${commit}^{commit}`], from) === null) {
    throw new XcError("E_BAD_ARG", `artifact repository ${from} does not contain commit ${commit.slice(0, 12)}…`);
  }
  if (git(["rev-parse", "--git-dir"], into) === null) {
    throw new XcError("E_BAD_ARG", `cannot fetch ${commit.slice(0, 12)}…: ${into} is not an inspectable git repository`);
  }
  git(["fetch", "--no-tags", "--quiet", from, "+refs/heads/*:refs/xcomms/artifact/*"], into);
  if (git(["cat-file", "-e", `${commit}^{commit}`], into) === null) {
    // A detached operator commit is on no branch; a local transport may still serve it by sha.
    git(["fetch", "--no-tags", "--quiet", from, commit], into);
  }
  if (git(["cat-file", "-e", `${commit}^{commit}`], into) === null) {
    throw new XcError("E_BAD_ARG",
      `commit ${commit.slice(0, 12)}… is readable in ${from} but could not be read in ${into} after fetching its ` +
      `branches (refs/xcomms/artifact/*): the artifact repository's object store is unreachable from this worktree.`);
  }
  return from;
}
