// LAT-2: the learner store is loaded once per RUN, not once per model request.
// Before this, `context` (which fires for every model request) re-read and
// re-parsed learner.json every time; a five-request turn paid five parses.
// Run: node tests/m37-context-cache.mjs
import { assert, loadExtension, contextFor, sessionStart, agentStart, modelRequest, bridgeCalls, tempRoot } from "./m37-harness.mjs";

const app = await loadExtension();
const target = contextFor("session-cache");
await sessionStart(app, target.ctx);
await agentStart(app, target.ctx);

// Five model requests inside ONE run: the transcript grows, as it does after each
// tool call in a real turn.
const transcript = [{ role: "user", content: "why does my loop not terminate?", timestamp: 1 }];
const firstBridgeCalls = bridgeCalls.length;
for (let request = 1; request <= 5; request++) {
  await modelRequest(app, target, transcript);
  assert.equal(transcript.length, 1, "the transcript is not mutated between requests");
  transcript.push({ role: "assistant", content: `${Array.from({ length: 2000 }).join(" ")}x`.slice(0, 2000), timestamp: 1 + request });
  transcript.push({ role: "user", content: `follow-up ${request}`, timestamp: 1 + request });
  transcript.pop(); // the hook only edits the newest user message; keep it last
}
// One editor capture for the run, not one per request (the run-scoped snapshot).
const stateCalls = bridgeCalls.slice(firstBridgeCalls).filter((call) => call.method === "getEditorState");
assert.equal(stateCalls.length, 1, `one editor capture per run (saw ${stateCalls.length})`);

// The plan/latency event pair is written once per run and states both numbers:
// five requests served, one file read. That is LAT-2's acceptance, readable from
// the event log rather than asserted about an internal.
const { readFile } = await import("node:fs/promises");
const { join } = await import("node:path");
const store = JSON.parse(await readFile(join(process.env.PI_MENTOR_HOME, "learner.json"), "utf8"));
const latency = (store.telemetry ?? []).filter((event) => event.type === "latency").at(-1);
assert.ok(latency, "the run wrote a latency event");
assert.equal(latency.requests, 5, "five model requests in the run");
assert.equal(latency.storeReads, 1, "exactly one read of learner.json for the run");
assert.ok(Number.isFinite(latency.storeReadMs), "the read time is measured, not omitted");

// The cached path's own cost is not fiction: a second run re-reads the file.
await agentStart(app, target.ctx);
await modelRequest(app, target, [{ role: "user", content: "next question", timestamp: 2 }]);
const after = JSON.parse(await readFile(join(process.env.PI_MENTOR_HOME, "learner.json"), "utf8"));
