const reread = await external.load();
assert.ok(reread.profile.notes.includes("written by another session"), "the external write landed");
assert.equal(external.version() > 0, true, "a committed write bumps the store version");
assert.ok(external.reads() >= 2, "reads() counts the real file reads, so a cache can be measured");
