#include <pthread.h>
#include <stdio.h>
#include <stdint.h>
static volatile int ran = 0;
static void init(void) { ran++; }
static void probe(uint64_t init_val, const char *label) {
    uint64_t once = init_val;
    ran = 0;
    /* timeout guard: run the call on a detached thread so a spin cannot hang us */
    pthread_once((pthread_once_t *)&once, init);
    printf("%-12s once_after=0x%llx ran=%d\n", label,
           (unsigned long long)once, ran);
}
int main(void) {
    probe(0x30b1bcbaULL, "0x30b1bcba");
    return 0;
}
EOF
cat > once_probe2.c <<'EOF'
#include <pthread.h>
#include <stdio.h>
#include <stdint.h>
#include <dispatch/dispatch.h>
static volatile int ran = 0;
static void init(void) { ran++; }
int main(void) {
    uint64_t once = 0x30b1bcbaULL;
    dispatch_semaphore_t sem = dispatch_semaphore_create(0);
    dispatch_async(dispatch_get_global_queue(0,0), ^{
        pthread_once((pthread_once_t *)&once, init);
        dispatch_semaphore_signal(sem);
    });
    long r = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 3LL*1000*1000*1000));
    printf("result=%s once_after=0x%llx ran=%d\n", r==0?"returned":"TIMEOUT(3s)",
           (unsigned long long)once, ran);
    return 0;
}
