// Seed raw Cortex-M image more aggressively: vector tables, BL targets, push-prologues.
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.*;
import ghidra.program.model.mem.*;
import ghidra.program.model.listing.*;
import ghidra.app.cmd.disassemble.DisassembleCommand;
import ghidra.app.cmd.function.CreateFunctionCmd;
import ghidra.program.model.scalar.Scalar;

public class Setup2 extends GhidraScript {
    void tryBlock(Memory mem, String n, long a, long sz) {
        try { mem.createUninitializedBlock(n, toAddr(a), sz, false); } catch (Exception e) { }
    }
    int seed(Program p, Address t, boolean force) {
        Memory mem = p.getMemory();
        if (t == null || !mem.contains(t)) return 0;
        if (getInstructionAt(t) == null) {
            DisassembleCommand dc = new DisassembleCommand(t, null, true);
            dc.applyTo(p, monitor);
        }
        Instruction i = getInstructionAt(t);
        if (i == null) return 0;
        if (getFunctionAt(t) == null) {
            CreateFunctionCmd cf = new CreateFunctionCmd(t);
            cf.applyTo(p, monitor);
            if (getFunctionAt(t) == null) return 0;
        }
        return 1;
    }
    @Override
    public void run() throws Exception {
        Program p = getCurrentProgram();
        Memory mem = p.getMemory();
        tryBlock(mem, "RAM", 0x20000000L, 0x20000L);
        tryBlock(mem, "PERIPH", 0x40000000L, 0x00100000L);
        tryBlock(mem, "PPB", 0xE0000000L, 0x100000L);
        int vec = 0, bl = 0, pro = 0;
        for (int i = 0; i < 256; i++) {
            long val = mem.getInt(toAddr(0x08000000L + i * 4)) & 0xFFFFFFFFL;
            if ((val & 0xFF000000L) == 0x08000000L) vec += seed(p, toAddr(val & ~1L), true);
        }
        // prologue + BL target scan over the whole image
        Address start = mem.getMinAddress(), end = mem.getMaxAddress();
        for (Address a = start; a.compareTo(end) < 0; a = a.add(2)) {
            int u = mem.getShort(a) & 0xFFFF;
            boolean prologue = (u >= 0xB400 && u <= 0xB5FF) || u == 0xE92D;
            if (prologue) { if (seed(p, a, true) == 1) { pro++; } }
        }
        println("SETUP2: vectors=" + vec + " prologues=" + pro);
    }
}
EOF
